// DrainageNode.cs is generated by Gemini

using UnityEngine;

public class DrainageNode : MonoBehaviour
{
    [Header("Obstacle Settings")]
    public int obstacleLevel = 0;
    public int maxLevel = 5;
    public float fillRate = 4f; 
    private float timer = 0f;

    [Header("Cleaning Settings")]
    public Transform player;
    public float cleaningRadius = 2.0f;

    [Header("Visuals (2D Sprites)")]
    [Tooltip("The SpriteRenderer that displays the debris")]
    public SpriteRenderer debrisRenderer;
    [Tooltip("Array of 5 sprites for levels 1 to 5. Level 0 will just hide the sprite.")]
    public Sprite[] debrisSprites;

    [Header("Debug Visuals")]
    public Color playerInRangeColor = Color.green; 
    private Renderer rend;
    private Color originalEmission;
    private bool isPlayerInRange = false;

    void Start()
    {
        if (player == null)
        {
            GameObject playerObj = GameObject.FindGameObjectWithTag("Player");
            if (playerObj != null) player = playerObj.transform;
        }

        rend = GetComponent<Renderer>();
        if (rend != null)
        {
            rend.material.EnableKeyword("_EMISSION");
            originalEmission = rend.material.GetColor("_EmissionColor");
        }

        timer = Random.Range(0f, 2f);
        UpdateVisuals();
    }

    void Update()
    {
        // 1. Handle Filling
        if (obstacleLevel < maxLevel)
        {
            timer += Time.deltaTime;
            if (timer >= fillRate)
            {
                obstacleLevel++;
                timer = 0f;
                UpdateVisuals();
            }
        }

        // 2. Handle Cleaning and Glow
        if (player != null)
        {
            Vector3 flatPlayerPosition = new Vector3(player.position.x, transform.position.y, player.position.z);
            float distance = Vector3.Distance(transform.position, flatPlayerPosition);

            if (distance <= cleaningRadius)
            {
                if (!isPlayerInRange)
                {
                    isPlayerInRange = true;
                    if (rend != null) rend.material.SetColor("_EmissionColor", playerInRangeColor * 2f);
                }

                if (obstacleLevel > 0)
                {
                    CleanDrainage();
                }
            }
            else
            {
                if (isPlayerInRange)
                {
                    isPlayerInRange = false;
                    if (rend != null) rend.material.SetColor("_EmissionColor", originalEmission);
                }
            }
        }
    }

    private void CleanDrainage()
    {
        obstacleLevel = 0;
        timer = 0f;
        UpdateVisuals();
    }

    private void UpdateVisuals()
    {
        if (debrisRenderer != null)
        {
            if (obstacleLevel == 0)
            {
                // Level 0: Hide the sprite entirely
                debrisRenderer.sprite = null;
            }
            else if (obstacleLevel > 0 && obstacleLevel <= debrisSprites.Length)
            {
                // Levels 1-5: Show the corresponding sprite 
                // Arrays start at 0, so Level 1 uses debrisSprites[0]
                debrisRenderer.sprite = debrisSprites[obstacleLevel - 1];
            }
        }
    }

    void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.green;
        Gizmos.DrawWireSphere(transform.position, cleaningRadius);
    }
}